@app.command()
def clean(
    path: Annotated[Path, typer.Argument(help="Directory to clean")],
    collection: Annotated[str, typer.Option(
        "--collection", "-c",
        help="Collection name"
    )],
    url: Annotated[str, typer.Option(
        "--url", "-u",
        help="Qdrant server URL"
    )] = "http://localhost:6333",
    state_file: Annotated[Optional[Path], typer.Option(
        "--state-file",
        help="Custom state file location"
    )] = None,
    deleted_only: Annotated[bool, typer.Option(
        "--deleted-only",
        help="Only remove entries for deleted files"
    )] = False,
    all: Annotated[bool, typer.Option(
        "--all",
        help="Remove all entries for this path (reset)"
    )] = False,
    yes: Annotated[bool, typer.Option(
        "--yes", "-y",
        help="Skip confirmation"
    )] = False,
    quiet: Annotated[bool, typer.Option(
        "--quiet", "-q"
    )] = False,
) -> None:
    """Clean database entries for a directory.

    Options:
    - Default: Remove entries for deleted files
    - --deleted-only: Only remove deleted files
    - --all: Remove ALL entries and reset state (full cleanup)
    """
    global _quiet
    _quiet = quiet

    if not path.exists() or not path.is_dir():
        display_error(f"Path does not exist or is not a directory: {path}")
        raise typer.Exit(1)

    if state_file is None:
        state_file = path / '.qdrant-index-state.json'

    if not state_file.exists():
        display_error(f"No state file found at {state_file}")
        raise typer.Exit(1)

    from qdrant_indexer.state import IndexState
    from qdrant_indexer.indexer import QdrantIndexer

    state = IndexState(state_file)
    state.load()

    indexer = QdrantIndexer(url, collection)

    if all:
        # Remove ALL entries
        if not yes:
            typer.confirm(
                f"This will remove ALL {len(state.files)} entries from '{collection}'. Continue?",
                abort=True
            )

        total_deleted = 0
        for file_path_str, file_state in state.files.items():
            try:
                indexer.delete_points_by_ids(file_state.chunk_ids)
                total_deleted += len(file_state.chunk_ids)
            except Exception as e:
                console.print(f"[red]Error removing {file_path_str}: {e}[/red]")

        # Remove state file
        state_file.unlink()

        display_success(f"Removed {total_deleted} points and deleted state file")

    else:
        # Remove only deleted files
        deleted_files = []
        for file_path_str in state.get_all_paths():
            if not Path(file_path_str).exists():
                deleted_files.append(file_path_str)

        if not deleted_files:
            if not quiet:
                console.print("[green]No deleted files to clean[/green]")
            return

        if not yes:
            typer.confirm(
                f"Remove {len(deleted_files)} deleted file entries from '{collection}'?",
                abort=True
            )

        total_deleted = 0
        for file_path_str in deleted_files:
            file_state = state.files.get(file_path_str)
            if file_state:
                try:
                    indexer.delete_points_by_ids(file_state.chunk_ids)
                    state.remove_file(Path(file_path_str))
                    total_deleted += len(file_state.chunk_ids)
                except Exception as e:
                    console.print(f"[red]Error removing {file_path_str}: {e}[/red]")

        state.save()
        display_success(f"Removed {total_deleted} points from {len(deleted_files)} deleted files")
